using littlecat.Server;
using Newtonsoft.Json;

namespace littlecat.Packets.Handlers.Status;

[PacketHandler(ClientState.Status, (int)PacketIds.Serverbound.Status.StatusRequest)]
public class StatusRequest : IPacketHandler
{
    public void HandlePacket(Server.Server server, MinecraftClient client)
    {
        Console.WriteLine("Got status request.");

        var statusResponse = JsonConvert.SerializeObject(new
        {
            version = new
            {
                name = "1.21.5",
                protocol = 770
            },
            players = new
            {
                max = 100,
                online = 0,
                // sample = new[]
                // {
                //     new
                //     {
                //         name = "Jowc",
                //         id = "1658caaf-0db9-43eb-ae89-1c22900d37c3"
                //     }
                // }
            },
            description = new
            {
                text = "what's good yall"
            },
            favicon =
                "data:image/png;base64,\n",
            enforcesSecureChat = false
        });

        var packet = new PacketBuilder((int)PacketIds.Clientbound.Status.StatusResponse).AppendString(statusResponse);
        client.GetStream().Write(packet.Build());
    }
}